import fs from 'fs';
import path from 'path';

const distDir = './dist';
const files = {};

function walk(dir, prefix = '') {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    const rel = prefix ? prefix + '/' + entry.name : entry.name;
    if (entry.isDirectory()) {
      walk(full, rel);
    } else {
      files['/' + rel] = fs.readFileSync(full).toString('base64');
    }
  }
}

walk(distDir);

const output = [
  '// Auto-generated by build-worker.mjs — do not edit',
  'const STATIC = ' + JSON.stringify(files, null, 2) + ';',
  '',
  'function decode(base64) {',
  '  const bin = atob(base64);',
  '  const bytes = new Uint8Array(bin.length);',
  '  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);',
  '  return bytes;',
  '}',
  '',
  'function mimeFor(p) {',
  "  if (p.endsWith('.html')) return 'text/html; charset=utf-8';",
  "  if (p.endsWith('.js')) return 'application/javascript; charset=utf-8';",
  "  if (p.endsWith('.css')) return 'text/css; charset=utf-8';",
  "  if (p.endsWith('.svg')) return 'image/svg+xml';",
  "  if (p.endsWith('.json')) return 'application/json';",
  "  if (p.endsWith('.png')) return 'image/png';",
  "  if (p.endsWith('.ico')) return 'image/x-icon';",
  "  return 'application/octet-stream';",
  '}',
  '',
  'export default {',
  '  async fetch(request, env) {',
  '    const url = new URL(request.url);',
  "    let pathname = url.pathname === '/' || url.pathname === '/super-admin' || url.pathname === '/super-admin/' ? '/index.html' : url.pathname;",
  '',
  '    if (STATIC[pathname]) {',
  '      return new Response(decode(STATIC[pathname]), {',
  "        headers: { 'Content-Type': mimeFor(pathname), 'Cache-Control': 'public, max-age=300' },",
  '      });',
  '    }',
  '',
  "    if (!pathname.includes('.')) {",
  "      return new Response(decode(STATIC['/index.html']), {",
  "        headers: { 'Content-Type': 'text/html; charset=utf-8' },",
  '      });',
  '    }',
  '',
  "    return new Response('Not found: ' + pathname, { status: 404 });",
  '  },',
  '};',
  ''
].join('\n');

fs.writeFileSync('./src/worker.js', output);
console.log('Built signal-admin Worker bundle with ' + Object.keys(files).length + ' static files.');
